function rowsOf(nodeName) {
  const root = $(nodeName).first()?.json ?? {};
  if (Array.isArray(root)) return root;
  if (Array.isArray(root.data)) return root.data;
  if (Array.isArray(root.items)) return root.items;
  if (Array.isArray(root.results)) return root.results;
  return [];
}
function contentId(row) {
  return String(row.content_id ?? row.contentId ?? row.video_id ?? row.videoId ?? row.contentID ?? row.id ?? '');
}
function competitorId(row) {
  return row.competitor_id ?? row.competitorId ?? row.competitor?.id ?? null;
}
function competitorName(row) {
  return String(row.competitor_name ?? row.competitorName ?? row.name ?? row.competitor?.name ?? 'Unknown competitor');
}
function toNum(v) {
  const n = Number(v ?? 0);
  return Number.isFinite(n) ? n : 0;
}

const perf=rowsOf('02 - Get Competitor KPI Data');
const monitoring=rowsOf('03 - Get Monitoring Activity');
const trends=rowsOf('04 - Get Trends');
const opportunities=rowsOf('05 - Get Opportunities');
const risks=rowsOf('06 - Get Risks');
const analyses=rowsOf('07 - Get Content Analysis');
const byCompetitor=new Map();
for(const p of perf){const id=String(competitorId(p)??competitorName(p));if(!byCompetitor.has(id))byCompetitor.set(id,{competitor_id:competitorId(p),competitor_name:competitorName(p),video_count:0,views:0,likes:0,comments:0});const g=byCompetitor.get(id);g.video_count++;g.views+=toNum(p.views);g.likes+=toNum(p.likes);g.comments+=toNum(p.comments);}
const kpis=[...byCompetitor.values()].map(g=>({...g,engagement_rate:g.views?Number(((g.likes+g.comments)/g.views*100).toFixed(2)):0}));
const alerts=[];
for(const row of monitoring){const ms=Array.isArray(row.metrics)?row.metrics:[];const cur=ms[0]??{},prev=ms[1]??{};const calc=(a,b)=>toNum(b)>0?Number(((toNum(a)-toNum(b))/toNum(b)*100).toFixed(2)):0;const v=calc(cur.views,prev.views),l=calc(cur.likes,prev.likes),c=calc(cur.comments,prev.comments);if(v>=1||l>=1||c>=1)alerts.push({competitor:competitorName(row),content_id:row.contentId??row.content_id??null,views_growth_rate:v,likes_growth_rate:l,comments_growth_rate:c});}
const topicCounts=new Map();for(const a of analyses){const t=String(a.topic??a.category??'Unknown');topicCounts.set(t,(topicCounts.get(t)||0)+1);}
const context={competitor_kpi:kpis.slice(0,30),competitor_alerts:alerts.slice(0,30),trends:trends.slice(0,20),opportunities:opportunities.slice(0,20),risks:risks.slice(0,20),content_analysis_summary:[...topicCounts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,15).map(([topic,count])=>({topic,count})),data_counts:{competitors:kpis.length,alerts:alerts.length,trends:trends.length,opportunities:opportunities.length,risks:risks.length,content_analyses:analyses.length}};
return [{json:{context,ai_prompt:`You are a strategic advisor for a social-media competitor analysis system. Synthesize only the facts in CONTEXT; do not invent metrics or evidence. Return one JSON object with keys: title, objective, description, priority (HIGH/MEDIUM/LOW), confidence (0-1), evidence (array of short evidence strings or IDs), target_audience, content_format, focus_topic, reason, expected_impact. Provide actionable strategy answering what to focus on, which audience, what content format/topic, why, and likely impact. If evidence is sparse, explicitly say so and lower confidence. The database strategy fields are title/objective/description/priority/confidence/evidence.\nCONTEXT:\n${JSON.stringify(context).slice(0,18000)}`}}];

function parseAI(value){if(value&&typeof value==='object')return value;if(typeof value==='string')return JSON.parse(value.trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim());throw new Error('AI Strategy Agent không trả về JSON.');}
const r=$input.first().json;
const txt =
  r.content?.parts?.[0]?.text ??
  r.output?.[0]?.content?.[0]?.text ??
  r.output?.[0]?.content?.text ??
  r.text ??
  r.message?.content;
const a=parseAI(txt);
const priority=['HIGH','MEDIUM','LOW'].includes(String(a.priority??'').toUpperCase())?String(a.priority).toUpperCase():'MEDIUM';
const baseConfidence=Number(a.confidence);const confidence=Number.isFinite(baseConfidence)?Math.max(0,Math.min(1,baseConfidence)):0.65;
const evidence=Array.isArray(a.evidence)?a.evidence.filter(Boolean).slice(0,20):[];
const title=String(a.title??'Evidence-Based Competitive Strategy');
const objective=String(a.objective??'');const description=String(a.description??'');
return [{json:{title,objective,description,priority,ai_confidence:confidence,evidence,target_audience:String(a.target_audience??''),content_format:String(a.content_format??''),focus_topic:String(a.focus_topic??''),reason:String(a.reason??''),expected_impact:String(a.expected_impact??''),is_valid:Boolean(title&&objective&&description&&evidence.length>0)}}];
